import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position, rotation, and scale from config
  if (config.scenePosition) {
    const pos = config.scenePosition;
    group.position.set(pos.x || 0, pos.y || 0, pos.z || 0);

    if (pos.rotationXYZ) {
      group.rotation.order = 'XYZ';
      group.rotation.set(pos.rotationXYZ.x || 0, pos.rotationXYZ.y || 0, pos.rotationXYZ.z || 0);
    }

    if (pos.scaleXYZ) {
      group.scale.set(pos.scaleXYZ.x || 1, pos.scaleXYZ.y || 1, pos.scaleXYZ.z || 1);
    }
  }

  // Create plane geometry with atlas-region aspect ratio (512:320 = 1.6:1)
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load brushed-metal texture
  const imageUrl = config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png';
  const texture = ctx.textureLoader.load(imageUrl);

  // Create material for textured plane
  const material = new THREE.MeshBasicNodeMaterial();
  material.map = texture;

  // Create and add plane mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Extract and prepare text content
  const textContent = typeof config.textContent === 'string'
    ? config.textContent
    : (config.textContent?.primary || 'Get started');

  // Parse color values
  const colors = config.colors || {};
  let textColor = colors.ink || '#16161d';
  if (typeof textColor === 'string') {
    textColor = parseInt(textColor.replace('#', ''), 16);
  }

  // Create MSDF text mesh via fontAtlas
  const textMesh = ctx.fontAtlas.createText({
    text: textContent,
    font: 'Lora',
    fontSize: 0.34, // headline scale from design tokens
    fontWeight: 400,
    color: textColor,
    align: 'center',
  });

  // Position text above plane surface
  textMesh.position.z = 0.1;
  group.add(textMesh);

  // Cleanup function: dispose all resources and kill timelines
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    gsap.killTweensOf(group);
    gsap.killTweensOf(textMesh);
  };

  // Event handlers (none for static label)
  group.userData.handlers = {};

  return group;
}
